import{_ as a,o as l,c as e,aw as n}from"./chunks/framework.DLufY-ao.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/common/git/command/rebase.md","filePath":"wiki/dev-commit/common/git/command/rebase.md"}'),p={name:"wiki/dev-commit/common/git/command/rebase.md"};function o(t,s,i,c,r,y){return l(),e("div",null,[...s[0]||(s[0]=[n(`<p>Позволяет взять все коммиты из одной ветки и применить их поверх другой</p><ul><li>Выполняет работу аналогичную cherry-pick, только для цепочки коммитов, перенося ветку на новое место</li><li>Коммит, который не даёт изменений называется пустым. rebase автоматически пропускает этот коммит</li></ul><h2 id="команды" tabindex="-1">Команды <a class="header-anchor" href="#команды" aria-label="Permalink to &quot;Команды&quot;">​</a></h2><h3 id="rebase" tabindex="-1">Rebase <a class="header-anchor" href="#rebase" aria-label="Permalink to &quot;Rebase&quot;">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebasedevelop#</span><span style="color:#50A14F;"> rebase</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase</span><span style="color:#986801;"> --continue</span><span style="color:#A0A1A7;font-style:italic;"> # продолжить rebase (вызывается при наличии конфликтов)</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase</span><span style="color:#986801;"> --skip</span><span style="color:#A0A1A7;font-style:italic;">     # пропустить коммит (вызывается при наличии конфликтов)</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase</span><span style="color:#986801;"> --abort</span><span style="color:#A0A1A7;font-style:italic;">    # отказаться от rebase (возвращает обратно HEAD - не изменит историю коммитов)</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase</span><span style="color:#986801;"> --quit</span><span style="color:#A0A1A7;font-style:italic;">     # отказаться от rebase (НЕ возвращает обратно HEAD - изменит историю коммитов)</span></span></code></pre></div><p>::: details--continue</p><ul><li>Флаг --continue позволяет продолжить rebase после фикса конфликта и перейти к следующему коммиту</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;"># Rebase develop в текущую ветку</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase</span><span style="color:#50A14F;"> develop</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># Если есть конфликт, то открывается редактор для фикса</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># После фикса добавляются изменения в staged</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> add</span><span style="color:#50A14F;"> .</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># Продолжить Rebase и перейти к следующему коммиту</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase--continue#</span><span style="color:#50A14F;"> Откроется</span><span style="color:#50A14F;"> редактор,</span><span style="color:#50A14F;"> где</span><span style="color:#50A14F;"> можно</span><span style="color:#50A14F;"> изменить</span><span style="color:#50A14F;"> название</span><span style="color:#50A14F;"> коммита</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># После закрытия редактора Rebase перейдет к следующему коммиту</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># Если следующего коммита нет, то Rebase завершится</span></span></code></pre></div><p>:::</p><p>::: details--skip</p><ul><li>Флаг --skip позволяет пропустить коммит из текущей ветки и взять изменения из develop</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;"># Rebase develop в текущую ветку</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase</span><span style="color:#50A14F;"> develop</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># Если есть конфликт, то открывается редактор для фикса</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># Пропустить коммит из текущей ветки и перейти к следующему коммиту</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase--skip\`\`\`</span></span>
<span class="line"></span>
<span class="line"><span style="color:#0184BC;">:::</span></span>
<span class="line"></span>
<span class="line"><span style="color:#0184BC;">:::</span><span style="color:#50A14F;"> details--abort</span></span>
<span class="line"><span style="color:#4078F2;">-</span><span style="color:#50A14F;"> Флаг </span><span style="color:#986801;">--abort</span><span style="color:#50A14F;"> позволяет вернусть состояние текушей ветки до rebase</span></span>
<span class="line"><span style="color:#4078F2;">-</span><span style="color:#50A14F;"> Маркер HEAD, будет перенесен обратно на текущую, а уже добавленные коммиты повиснут в воздухе (на них не будет указывать ни один указатель) и будут вскоре удалены</span></span>
<span class="line"></span>
<span class="line"><span style="color:#50A14F;">\`\`\`</span><span style="color:#4078F2;">bash</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># Rebase develop в текущую ветку</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase</span><span style="color:#50A14F;"> develop</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># Если есть конфликт, то открывается редактор для фикса</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># Откатиться в состояние до rebase</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase--abort\`\`\`</span></span>
<span class="line"></span>
<span class="line"><span style="color:#0184BC;">:::</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">### Интерактивный Rebase</span></span>
<span class="line"></span>
<span class="line"><span style="color:#50A14F;">\`\`\`</span><span style="color:#4078F2;">bash</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase</span><span style="color:#986801;"> -idevelop</span><span style="color:#383A42;"># интерактивный rebase на другую ветку</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase</span><span style="color:#986801;"> -i</span><span style="color:#50A14F;"> HEAD~3</span><span style="color:#A0A1A7;font-style:italic;">  # интерактивный rebase внутри ветки (изменить историю последних 3х коммитов)</span></span></code></pre></div><ul><li>При интерактивном rebase можно работать только с новыми коммитами, добавленными для текущей ветки. Пример: при git rebase -i master в ветку feature, в окне интерактивного rebase будут отражены коммиты только для feature</li><li>В начала rebase запустится окно редактора, где можно указать определенную команду для каждого коммита</li><li>При этом переписывается история коммитов - у каждого коммита будет новый хэш</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">›</span><span style="color:#50A14F;"> pick</span><span style="color:#50A14F;">  cb923a7</span><span style="color:#50A14F;"> MessageCommit1</span></span>
<span class="line"><span style="color:#4078F2;">›</span><span style="color:#50A14F;"> fixup</span><span style="color:#50A14F;"> 0a101a7</span><span style="color:#50A14F;"> MessageCommit2</span></span>
<span class="line"><span style="color:#4078F2;">›</span><span style="color:#50A14F;"> fixup</span><span style="color:#50A14F;"> 67e7534</span><span style="color:#50A14F;"> MessageCommit3</span></span></code></pre></div><h4 id="команды-1" tabindex="-1">Команды <a class="header-anchor" href="#команды-1" aria-label="Permalink to &quot;Команды&quot;">​</a></h4><ul><li>pick p - использовать коммит без изменений (по умолчанию)</li><li>reword r - использовать текущий коммит с возможностью изменения сообщения коммита</li><li>drop d - удаление коммита (вместо этого можно удалить строку с коммитом)</li><li>fixup f - будет объединен с предыдущем коммитом в списке, но без изменения сообщения коммита</li><li>squash s - будет объединен с предыдущем коммитом в списке</li><li>edit e - отредактировать коммит (когда git дойдёт до коммита, выполнится отстановка и git предложит выполнить действия)</li><li>exec x - выполнить скрипт для указанного коммита</li><li>break b - остановиться здесь (продолжить rebase позже с git rebase --continue)</li><li>label l - добавить метку для текущего HEAD с заданным именем</li><li>reset t - сбросить HEAD до указанной метки</li><li>merge m - создать merge-commit, используя message исходного merge-commit (или однострочный, если исходный merge-commit не был указан)</li></ul><h2 id="алгоритм-работы" tabindex="-1">Алгоритм работы <a class="header-anchor" href="#алгоритм-работы" aria-label="Permalink to &quot;Алгоритм работы&quot;">​</a></h2><p>Задача: загрузить изменения из master в feature</p><p>Подготовка: Создание ветки feature и добавление коммитов в master и feature</p><ul><li>feature откалывается от master</li><li>В каждую ветку поочередно добавляются коммиты</li></ul><h4 id="порядок-коммитов" tabindex="-1">Порядок коммитов <a class="header-anchor" href="#порядок-коммитов" aria-label="Permalink to &quot;Порядок коммитов&quot;">​</a></h4><ol><li>master-0 - master</li><li>feature-1 - feature</li><li>master-1 - master</li><li>feature-2 - feature</li><li>master-2 - master</li></ol><p>1 Rebase: Создание новой ветки feature&#39;</p><ul><li>Создается новая временная ветка feature&#39; на основе актуального состояния master</li></ul><p>2 Rebase: Копирование всех коммитов feature поверх текущей вершины master для временной ветки feature&#39;</p><ul><li>Работает аналогично cherry-pick: последовательно берутся изменения каждого коммита из feature и применяются к вершине master: для каждого из коммитов в feature берётся его дельта и сохраняется во временный файл</li><li>Из каждого временного файла создается новый коммит с тем же автором и описанием, но другим хэшем</li></ul><p>3 Rebase: Перенос HEAD из ветки feature в ветку feature&#39;</p><ul><li>После копирования коммитов, ссылка feature переносится на вершину новосозданной ветки feature&#39;</li><li>Теперь ветка feature&#39; (копия ветки feature) основана на последнем состоянии master</li></ul><hr><h2 id="плюсы-и-минусы" tabindex="-1">Плюсы и минусы <a class="header-anchor" href="#плюсы-и-минусы" aria-label="Permalink to &quot;Плюсы и минусы&quot;">​</a></h2><ul><li>При rebase меняеся история: меняются все хэши коммитов</li><li>Если над веткой работает несолько человек и был rebase, то остальные разработчики не смогут нормально сделать pull, при условии наличия локальных коммитов. Пойдут конфликты. Рекомендуется, если над веткой работает 1 человек</li><li>По истории нельзя будет посмотреть в какие моменты происходило подобновление ветки</li></ul><hr><ul><li>Красивая и понятная история</li><li>Не появляется лишних коммитов, в отличие от merge-коммитов</li></ul><h2 id="примеры" tabindex="-1">Примеры <a class="header-anchor" href="#примеры" aria-label="Permalink to &quot;Примеры&quot;">​</a></h2><details class="details custom-block"><summary>Актуализация ветки через rebase</summary><ul><li>Есть 2 ветки: develop и feature</li><li>Необходимо актуализаировать ветку feature: подтянуть последние изменения из develop и решить конфликты если они есть</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> checkoutdevelop#</span><span style="color:#50A14F;"> перейти</span><span style="color:#50A14F;"> в</span><span style="color:#50A14F;"> ветку</span><span style="color:#50A14F;"> develop</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> fetch</span><span style="color:#50A14F;"> origin</span><span style="color:#A0A1A7;font-style:italic;">       # подтянуть последние изменени для develop</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> pull</span><span style="color:#A0A1A7;font-style:italic;">               # взять последние изменени для develop</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> checkoutfeature#</span><span style="color:#50A14F;"> перейти</span><span style="color:#50A14F;"> в</span><span style="color:#50A14F;"> ветку</span><span style="color:#50A14F;"> feature</span></span></code></pre></div><ul><li>На выбор: делать rebase на ветку локального или удаленного репозитория</li><li>Если делать rebase с origin/develop, то нет необходимости делать git pull</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase</span><span style="color:#986801;"> -idevelop</span><span style="color:#383A42;"># взять последние изменения из develop</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> rebase</span><span style="color:#986801;"> -iorigin/develop</span><span style="color:#383A42;"># взять последние изменения из origin/develop</span></span></code></pre></div><ul><li>Если есть конфликты merge, откроется редактор</li><li>Пофиксить конфликты</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> add</span><span style="color:#50A14F;"> .</span><span style="color:#A0A1A7;font-style:italic;">             # добавить измененные файлы вstagedgit rebase --continue # если несколько коммитов, то преходим к фиксу следующего коммита</span></span></code></pre></div><ul><li>Если есть конфликт, то его нужно фиксить в каждом коммите</li><li>После фикса всех коммитов и добавления в staged (через git add), Working Tree будет чистое: не нужно ничего коммитить</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> push</span><span style="color:#50A14F;"> origin</span><span style="color:#50A14F;"> HEAD</span><span style="color:#A0A1A7;font-style:italic;"> # отправка изменений на удаленный репозиторий</span></span></code></pre></div><ul><li>Rebase изменяет историю коммитов и указатель, поэтому, если сначала сделать git push, а потом git rebase на локальном репозитории, то повторный push придется делать через push --force</li><li>При использовании push --force, сервер перепишет историю в ветке, которая будет повторять историю локальной ветки</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> push</span><span style="color:#986801;"> --force</span><span style="color:#50A14F;"> origin</span><span style="color:#50A14F;"> HEAD</span><span style="color:#A0A1A7;font-style:italic;"> # отправка изменений на удаленный репозиторий</span></span></code></pre></div></details>`,35)])])}const u=a(p,[["render",o]]);export{d as __pageData,u as default};
